class OrderedStream {
    private final String[] values;
    private final BitSet ready;
    private int ptr;

    public OrderedStream(int n) {
        values = new String[n + 1];
        ready = new BitSet(n + 1);
        ptr = 1;
    }

    public List<String> insert(int idKey, String value) {
        values[idKey] = value;
        ready.set(idKey);
        List<String> chunk = new ArrayList<>();
        while (ptr < values.length && ready.get(ptr)) {
            chunk.add(values[ptr]);
            ptr++;
        }
        return chunk;
    }
}

import java.util.*;

class OrderedStream {
    private final TreeMap<Integer, String> pending;
    private int ptr;

    public OrderedStream(int n) {
        pending = new TreeMap<>();
        ptr = 1;
    }

    public List<String> insert(int idKey, String value) {
        pending.put(idKey, value);
        List<String> chunk = new ArrayList<>();
        while (!pending.isEmpty()) {
            Map.Entry<Integer, String> first = pending.firstEntry();
            if (first.getKey() != ptr) {
                break;
            }
            chunk.add(first.getValue());
            pending.pollFirstEntry();
            ptr++;
        }
        return chunk;
    }
}

import java.util.*;

class OrderedStream {
    private final String[] values;
    private final PriorityQueue<Integer> readyIds;
    private int ptr;

    public OrderedStream(int n) {
        values = new String[n + 1];
        readyIds = new PriorityQueue<>();
        ptr = 1;
    }

    public List<String> insert(int idKey, String value) {
        values[idKey] = value;
        readyIds.add(idKey);
        List<String> chunk = new ArrayList<>();
        while (!readyIds.isEmpty() && readyIds.peek() == ptr) {
            readyIds.poll();
            chunk.add(values[ptr]);
            ptr++;
        }
        return chunk;
    }
}
